import json, re, math, heapq, collections, itertools, copy, sys, os, traceback

def node_by_title(doc, title):
    for node in doc.get('nodes', []):
        if node.get('title') == title:
            return node
    return None

def get_table_rows(node):
    rows=[]
    for idx, row in enumerate(node['table']['rows']):
        rows.append((idx, dict(zip(node['table']['columns'], row))))
    return rows

